CREATE TABLE IF NOT EXISTS dialogs (id SERIAL PRIMARY KEY,user1_id INTEGER NOT NULL,user2_id INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(user1_id<user2_id),UNIQUE(user1_id,user2_id));
CREATE TABLE IF NOT EXISTS messages (id SERIAL PRIMARY KEY,dialog_id INTEGER NOT NULL REFERENCES dialogs(id) ON DELETE CASCADE,sender_id INTEGER NOT NULL,message TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
